type EventRecord = OacaEventSummary & {
  timezone?:string; canManage:boolean; presentCount:number; absentCount:number; notRecordedCount:number;
  attendanceStatus?:AttendanceStatus|null; checkinOpen:boolean; sourceSystem?:string|null; publicationError?:string|null;
};
type RosterRow = { studentId:string; displayName:string; registrationStatus:string; registrationSource:string; attendanceStatus:AttendanceStatus; attendanceSource:string|null; version:number; updatedAt:string };
type Notice = { id:string; eventId:string|null; category:string; title:string; body:string; deepLink:string; readAt:string|null; dismissedAt:string|null; createdAt:string };
type Rule = { id:string; type:string; offsetMinutes:number|null; channels:string[]; enabled:boolean; scheduledFor:string|null; generation:number };
type CoordinatorRule = { activityType:string; deliveryMode:"immediate"|"hourly"|"off"; channels:string[] };
type Correction = { id:string; eventId?:string; studentId?:string; displayName?:string; requestedStatus:AttendanceStatus; explanation?:string; status:string; createdAt:string; resolutionNote?:string };
type Thread = { id:string; studentId:string; studentName:string; messages:Array<{ id:string; senderId:string; body:string; direction:string; channel:string; createdAt:string }> };
type StaffOption = { userId:string; displayName:string; groupKey?:string; groupLabel?:string };
type PersonOption = { userId:string; displayName:string; role?:string };
type AudienceOptions = { cohorts:string[]; phases:string[]; years:string[]; campuses:string[]; organizations:Array<{id:string;name:string;college?:string}>; memberRoles:Array<{key:string;label:string}>; people:PersonOption[]; providers:Array<{id:string;displayName:string}> };
type Activity = { id:string; eventId:string; activityType:string; summary:string; createdAt:string };
type Workspace = { events:EventRecord[]; roster:RosterRow[]; hosts:Array<{userId:string;displayName:string;role:string}>; staffOptions:StaffOption[]; audienceOptions:AudienceOptions; corrections:Correction[]; notifications:Notice[]; preferences:{emailEnabled:boolean;smsEnabled:boolean;phoneVerified:boolean;quietHoursStart:string|null;quietHoursEnd:string|null;timezone:string}; pushSubscriptions:Array<{id:string;provider:string;deviceLabel:string|null;permissionStatus:string;createdAt:string}>; notificationRules:Rule[]; coordinatorAlertRules:CoordinatorRule[]; activity:Activity[]; deliveries:Record<string,number>; threads:Thread[]; unreadCount:number; recipientVersion:number; recipientCount:number };
type StudentOption = { id:string; displayName:string };
type DetailTab = "attendance"|"checkin"|"notify"|"messages"|"details";
type ImportPackage = { id:string; status:string; source_event_rows:number; source_attendance_rows:number; occurrence_count:number; matched_students:number; merged_duplicates:number; quality_summary:Record<string,unknown>; requested_by:string; reviewed_by:string|null; reviewed_at:string|null; completed_at:string|null; created_at:string };
type Preview = { count:number; sample:PersonOption[]; excludedCount:number; additions?:number; removals?:number; version?:number };
type AttendeeRuleDraft = { type:string; label:string; offsetMinutes:number|null; enabled:boolean; email:boolean; push:boolean; sms:boolean };
type CoordinatorRuleDraft = { activityType:string; label:string; deliveryMode:"immediate"|"hourly"|"off"; email:boolean; push:boolean; sms:boolean };
type EventDraft = { title:string; description:string; category:string; accessibilityDetails:string; publicCatalog:boolean; startsAt:string; endsAt:string; location:string; modality:string; capacity:string; audience:OacaAudience; coordinatorUserIds:string[]; attendeeRules:AttendeeRuleDraft[]; coordinatorRules:CoordinatorRuleDraft[] };

const emptyAudienceOptions:AudienceOptions={cohorts:[],phases:[],years:[],campuses:[],organizations:[],memberRoles:[],people:[],providers:[]};
const emptyWorkspace:Workspace={events:[],roster:[],hosts:[],staffOptions:[],audienceOptions:emptyAudienceOptions,corrections:[],notifications:[],preferences:{emailEnabled:true,smsEnabled:false,phoneVerified:false,quietHoursStart:null,quietHoursEnd:null,timezone:"America/Los_Angeles"},pushSubscriptions:[],notificationRules:[],coordinatorAlertRules:[],activity:[],deliveries:{},threads:[],unreadCount:0,recipientVersion:0,recipientCount:0};
const attendanceLabels:Record<AttendanceStatus,string>={present:"Present",absent:"Absent",not_recorded:"Not recorded"};
const wizardSteps=["Details","Audience","Coordinators","Notifications","Review"] as const;
const attendeeRuleDefaults:AttendeeRuleDraft[]=[
  {type:"publication",label:"Invitation and publication",offsetMinutes:null,enabled:true,email:true,push:false,sms:false},
  {type:"registration_confirmation",label:"Registration confirmation",offsetMinutes:null,enabled:true,email:true,push:false,sms:false},
  {type:"waitlist_confirmation",label:"Waitlist confirmation",offsetMinutes:null,enabled:true,email:true,push:false,sms:false},
  {type:"waitlist_promotion",label:"Waitlist promotion",offsetMinutes:null,enabled:true,email:true,push:true,sms:false},
  {type:"reminder",label:"24-hour reminder",offsetMinutes:1440,enabled:true,email:true,push:true,sms:false},
  {type:"reminder",label:"1-hour reminder",offsetMinutes:60,enabled:true,email:true,push:true,sms:false},
  {type:"event_change",label:"Time, location, or format change",offsetMinutes:null,enabled:true,email:true,push:true,sms:false},
  {type:"cancellation",label:"Cancellation",offsetMinutes:null,enabled:true,email:true,push:true,sms:true},
  {type:"checkin_open",label:"Check-in opening",offsetMinutes:null,enabled:false,email:false,push:true,sms:false},
  {type:"follow_up",label:"Follow-up and feedback",offsetMinutes:null,enabled:true,email:true,push:false,sms:false},
];
const coordinatorRuleDefaults:CoordinatorRuleDraft[]=[
  {activityType:"rsvp",label:"RSVP activity",deliveryMode:"hourly",email:true,push:false,sms:false},
  {activityType:"waitlist",label:"Waitlist activity",deliveryMode:"hourly",email:true,push:false,sms:false},
  {activityType:"event_message",label:"Event messages and SMS replies",deliveryMode:"immediate",email:true,push:true,sms:false},
  {activityType:"checkin",label:"Check-ins and walk-ins",deliveryMode:"hourly",email:false,push:false,sms:false},
  {activityType:"correction",label:"Attendance corrections",deliveryMode:"immediate",email:true,push:true,sms:false},
  {activityType:"delivery_failure",label:"Delivery failures",deliveryMode:"immediate",email:false,push:true,sms:false},
  {activityType:"event_change",label:"Event changes and cancellations",deliveryMode:"immediate",email:true,push:true,sms:false},
];

function newDraft(userId:string):EventDraft { return {title:"",description:"",category:"Community",accessibilityDetails:"",publicCatalog:false,startsAt:"",endsAt:"",location:"",modality:"in_person",capacity:"",audience:{includeAllMembers:true},coordinatorUserIds:[userId],attendeeRules:attendeeRuleDefaults.map((item)=>({...item})),coordinatorRules:coordinatorRuleDefaults.map((item)=>({...item}))}; }
function toggleValue(values:string[]|undefined,value:string,checked:boolean){const next=new Set(values||[]);if(checked)next.add(value);else next.delete(value);return [...next];}
function toIso(value:string){return value?new Date(value).toISOString():"";}
function localInput(value:string|null|undefined){if(!value)return "";const date=new Date(value);const local=new Date(date.valueOf()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);}
function staffCategory(notice:Notice){return notice.category.startsWith("event_staff_");}
function notificationLabel(category:string){return category.replace(/^event_staff_/,"").replaceAll("_"," ");}

function QrImage({value,label}:{value:string;label:string}){
  const [source,setSource]=useState("");
  useEffect(()=>{let active=true;void QRCode.toDataURL(value,{width:280,margin:2,errorCorrectionLevel:"M",color:{dark:"#252323",light:"#ffffff"}}).then((data)=>{if(active)setSource(data);});return()=>{active=false;};},[value]);
  // A generated QR data URL is intentionally rendered directly; it has no optimizable asset URL.
  // eslint-disable-next-line @next/next/no-img-element
  return source?<img className="event-qr" src={source} alt={label} width={280} height={280}/>:<div className="event-qr event-qr--loading" role="status">Preparing secure code…</div>;
}

async function detectQrFromImage(file:File){
  type Detector=new(options:{formats:string[]})=>{detect(source:ImageBitmap):Promise<Array<{rawValue:string}>>};
  const Barcode=(window as unknown as {BarcodeDetector?:Detector}).BarcodeDetector;
  if(!Barcode)throw new Error("This browser cannot scan an image. Enter the secure code manually instead.");
  const bitmap=await createImageBitmap(file);try{return(await new Barcode({formats:["qr_code"]}).detect(bitmap))[0]?.rawValue||"";}finally{bitmap.close();}
}

function AttendanceControl({row,disabled,onChange}:{row:RosterRow;disabled:boolean;onChange:(row:RosterRow,status:AttendanceStatus)=>void}){
  return <fieldset className="attendance-control" disabled={disabled}><legend className="sr-only">Attendance for {row.displayName}</legend>{(["present","absent","not_recorded"] as AttendanceStatus[]).map((status)=><button type="button" key={status} className={row.attendanceStatus===status?`attendance-${status} active`:`attendance-${status}`} aria-pressed={row.attendanceStatus===status} onClick={()=>onChange(row,status)}>{attendanceLabels[status]}</button>)}</fieldset>;
}

function ChannelChecks({email,push,sms,onChange}:{email:boolean;push:boolean;sms:boolean;onChange:(field:"email"|"push"|"sms",checked:boolean)=>void}){
  return <div className="channel-options channel-options--compact"><label><input type="checkbox" checked readOnly/><span>Compass</span></label><label><input type="checkbox" checked={email} onChange={(event)=>onChange("email",event.target.checked)}/><span>Email</span></label><label><input type="checkbox" checked={push} onChange={(event)=>onChange("push",event.target.checked)}/><span>App</span></label><label><input type="checkbox" checked={sms} onChange={(event)=>onChange("sms",event.target.checked)}/><span>SMS</span></label></div>;
}

function ImportProgress({item}:{item:ImportPackage}){
  const steps=["Secure upload","Security scan","Independent review","Processing","Complete"];
  const index=item.status==="awaiting_scan"?1:item.status==="ready_for_review"?2:["approved","importing"].includes(item.status)?3:["completed","completed_with_issues"].includes(item.status)?4:0;
  const finished=["completed","completed_with_issues"].includes(item.status);
  const next=item.status==="awaiting_scan"?"Waiting for both files to pass security scanning.":item.status==="ready_for_review"?"A second authorized reviewer can approve this import.":item.status==="approved"?"Approved and waiting for the secure processor.":item.status==="importing"?"Normalization is running now.":item.status==="completed_with_issues"?"Completed. Review the quarantined exceptions.":item.status==="completed"?"Completed and added to event history.":item.status==="rejected"?"Rejected. No records were released.":item.status==="failed"?"Processing failed. Review the error before retrying.":"Upload received.";
  return <div className="import-progress"><div className="import-progress__steps" aria-label={`Import status: ${item.status.replaceAll("_"," ")}`}>{steps.map((step,stepIndex)=><span key={step} className={finished&&stepIndex<=index||stepIndex<index?"complete":stepIndex===index?"current":""}><i aria-hidden="true">{finished&&stepIndex<=index||stepIndex<index?"✓":stepIndex+1}</i>{step}</span>)}</div><p>{next}</p></div>;
}

export function OacaEventWorkspace({api,supabase,context,canCreateEvents,canManageImports,seedEvents,students,onBack}:{api:PilotApiClient;supabase:SupabaseClient;context:AuthorizationContext;canCreateEvents:boolean;canManageImports:boolean;seedEvents:OacaEventSummary[];students:StudentOption[];onBack:()=>void}){
  const [workspace,setWorkspace]=useState<Workspace>({...emptyWorkspace,events:seedEvents.map((event)=>({...event,canManage:true,presentCount:0,absentCount:0,notRecordedCount:0,checkinOpen:false}))});
  const [dateFrom,setDateFrom]=useState("");const [dateTo,setDateTo]=useState("");
  const [selectedId,setSelectedId]=useState("");const [bucket,setBucket]=useState<"today"|"upcoming"|"past">("today");const [query,setQuery]=useState("");const [tab,setTab]=useState<DetailTab>("attendance");
  const [busy,setBusy]=useState(false);const [savingStudents,setSavingStudents]=useState<Set<string>>(new Set());const [message,setMessage]=useState("");
  const [showCreator,setShowCreator]=useState(false);const [wizardStep,setWizardStep]=useState(0);const [notificationsReviewed,setNotificationsReviewed]=useState(false);const [draft,setDraft]=useState<EventDraft>(()=>newDraft(context.userId));const [preview,setPreview]=useState<Preview|null>(null);
  const [noticeEvent,setNoticeEvent]=useState("");const [noticeTypeFilter,setNoticeTypeFilter]=useState("");
  const [checkinToken,setCheckinToken]=useState("");const [checkinUrl,setCheckinUrl]=useState("");const [checkinCloses,setCheckinCloses]=useState("");const [scanToken,setScanToken]=useState("");const [walkIn,setWalkIn]=useState("");
  const [noticeType,setNoticeType]=useState("announcement");const [noticeTitle,setNoticeTitle]=useState("");const [noticeBody,setNoticeBody]=useState("");const [email,setEmail]=useState(true);const [push,setPush]=useState(false);const [sms,setSms]=useState(false);const [allActive,setAllActive]=useState(false);
  const [threadId,setThreadId]=useState("");const [threadBody,setThreadBody]=useState("");const [threadSms,setThreadSms]=useState(false);const [hostUser,setHostUser]=useState("");
  const [eventsFile,setEventsFile]=useState<File>();const [logsFile,setLogsFile]=useState<File>();const [importPackages,setImportPackages]=useState<ImportPackage[]>([]);const [refreshPreview,setRefreshPreview]=useState<Preview|null>(null);
  const [edit,setEdit]=useState({title:"",description:"",category:"Community",accessibilityDetails:"",publicCatalog:false,startsAt:"",endsAt:"",location:"",modality:"in_person",capacity:""});
  const selected=workspace.events.find((event)=>event.id===selectedId);
  const isSynthetic=context.userId==="synthetic-creator";
  const load=useCallback(async(eventId=selectedId)=>{const next=await api.request<Workspace>(`/api/oaca/events/workspace${eventId?`?eventId=${encodeURIComponent(eventId)}`:""}`);setWorkspace({...emptyWorkspace,...next,audienceOptions:{...emptyAudienceOptions,...next.audienceOptions}});if(canManageImports)setImportPackages(await api.request<ImportPackage[]>("/api/oaca/event-imports"));},[api,canManageImports,selectedId]);
  useEffect(()=>{const task=window.setTimeout(()=>void load().catch((error)=>setMessage(error instanceof Error?error.message:"Events could not be loaded.")),0);return()=>window.clearTimeout(task);},[load]);
  useEffect(()=>{if(!selected)return;const task=window.setTimeout(()=>{setEdit({title:selected.title,description:selected.description,category:selected.category||"Community",accessibilityDetails:selected.accessibilityDetails||"",publicCatalog:Boolean(selected.publicCatalog),startsAt:localInput(selected.startsAt),endsAt:localInput(selected.endsAt),location:selected.location||"",modality:selected.modality,capacity:selected.capacity?.toString()||""});setNoticeTitle(selected.title);},0);return()=>window.clearTimeout(task);},[selected]);
  const filteredEvents=useMemo(()=>workspace.events.filter((event)=>((dateFrom||dateTo)?(!dateFrom||campusDate(event.endsAt||event.startsAt)>=dateFrom)&&(!dateTo||campusDate(event.startsAt)<=dateTo):eventBucket(event.startsAt,event.endsAt)===bucket)&&`${event.title} ${event.location||""}`.toLowerCase().includes(query.toLowerCase())),[bucket,query,workspace.events,dateFrom,dateTo]);
  const staffNotices=useMemo(()=>workspace.notifications.filter(staffCategory).filter((notice)=>(!noticeEvent||notice.eventId===noticeEvent)&&(!noticeTypeFilter||notice.category===noticeTypeFilter)),[noticeEvent,noticeTypeFilter,workspace.notifications]);
  const staffNoticeTypes=[...new Set(workspace.notifications.filter(staffCategory).map((notice)=>notice.category))];
  const staffGroups=useMemo(()=>{const groups=new Map<string,StaffOption[]>();for(const person of workspace.staffOptions){const label=person.groupLabel||"Compass staff";groups.set(label,[...(groups.get(label)||[]),person]);}return [...groups.entries()];},[workspace.staffOptions]);
  const activeThread=workspace.threads.find((item)=>item.id===threadId)||workspace.threads[0];

  const openEvent=async(eventId:string,openMessages=false)=>{const event=workspace.events.find((item)=>item.id===eventId);setSelectedId(eventId);setTab(openMessages?"messages":"attendance");if(event&&!event.canManage){setMessage("You can see this event summary, but rosters and private activity are limited to its coordinators.");return;}setMessage("");try{setWorkspace({...emptyWorkspace,...await api.request<Workspace>(`/api/oaca/events/workspace?eventId=${encodeURIComponent(eventId)}`)});}catch(error){setSelectedId("");setMessage(error instanceof Error?error.message:"The event could not be opened.");}};
  const actOnNotice=async(id:string,action:"read"|"dismiss")=>{try{await api.request("/api/platform/notifications/action",{method:"POST",body:{notificationId:id,action}});await load("");}catch(error){setMessage(error instanceof Error?error.message:"The notification could not be updated.");}};
  const previewAudience=async(audience=draft.audience)=>{try{const result=await api.request<Preview>("/api/oaca/events/audience-preview",{method:"POST",body:{audience}});setPreview(result);return result;}catch(error){setMessage(error instanceof Error?error.message:"The audience could not be previewed.");return null;}};
  const publishReady=Boolean(draft.title.trim()&&draft.startsAt&&validateOacaAudience(draft.audience)&&draft.coordinatorUserIds.length&&notificationsReviewed);
  const createEvent=async(action:"draft"|"publish")=>{if(action==="publish"&&!publishReady){setMessage("Complete the event details, audience, coordinators, and notification review before publishing.");return;}if(!draft.title.trim()||!draft.startsAt){setMessage("Add an event title and start time before saving.");setWizardStep(0);return;}setBusy(true);try{const saved=await api.request<{id:string;status:string;recipientCount?:number;publication_error?:string|null;publicationError?:string|null}>("/api/oaca/events",{method:"POST",body:{title:draft.title,description:draft.description,category:draft.category,accessibilityDetails:draft.accessibilityDetails,publicCatalog:draft.publicCatalog,startsAt:toIso(draft.startsAt),endsAt:draft.endsAt?toIso(draft.endsAt):null,location:draft.location,modality:draft.modality,capacity:draft.capacity||null,audience:draft.audience,coordinatorUserIds:draft.coordinatorUserIds,attendeeNotificationRules:draft.attendeeRules.map((rule)=>({type:rule.type,offsetMinutes:rule.offsetMinutes,enabled:rule.enabled,channels:notificationChannels(rule)})),coordinatorAlertRules:draft.coordinatorRules.map((rule)=>({activityType:rule.activityType,deliveryMode:rule.deliveryMode,channels:notificationChannels(rule)})),action}});setDraft(newDraft(context.userId));setPreview(null);setNotificationsReviewed(false);setWizardStep(0);setShowCreator(false);setBucket("upcoming");const publicationError=saved.publicationError||saved.publication_error;setMessage(action==="publish"&&saved.status!=="published"?`Event saved as a recoverable draft. Publication stopped: ${publicationError||"review the event and try again."}`:action==="publish"?`Event published. ${saved.recipientCount??"The selected"} recipients were resolved and notifications were scheduled.`:"Event saved as a draft. You can finish and publish it from Upcoming.");await load("");}catch(error){setMessage(error instanceof Error?`${error.message} Your work remains available in this form.`:"The event could not be saved. Your work remains available in this form.");}finally{setBusy(false);}};
  const setAudienceValues=(key:keyof OacaAudience,value:string,checked:boolean)=>{setDraft((current)=>({...current,audience:{...current.audience,[key]:toggleValue(current.audience[key] as string[]|undefined,value,checked)}}));setPreview(null);};
  const updateAttendeeRule=(index:number,updates:Partial<AttendeeRuleDraft>)=>setDraft((current)=>({...current,attendeeRules:current.attendeeRules.map((rule,itemIndex)=>itemIndex===index?{...rule,...updates}:rule)}));
  const updateCoordinatorRule=(index:number,updates:Partial<CoordinatorRuleDraft>)=>setDraft((current)=>({...current,coordinatorRules:current.coordinatorRules.map((rule,itemIndex)=>itemIndex===index?{...rule,...updates}:rule)}));

  const updateAttendance=async(row:RosterRow,status:AttendanceStatus)=>{if(row.attendanceStatus===status)return;setSavingStudents((current)=>new Set(current).add(row.studentId));setWorkspace((current)=>({...current,roster:current.roster.map((item)=>item.studentId===row.studentId?{...item,attendanceStatus:status}:item)}));try{const result=await api.request<{version:number}>("/api/oaca/events/attendance",{method:"POST",body:{eventId:selectedId,studentId:row.studentId,status,version:row.version}});setWorkspace((current)=>({...current,roster:current.roster.map((item)=>item.studentId===row.studentId?{...item,attendanceStatus:status,version:result.version}:item)}));setMessage(`${row.displayName}: ${attendanceLabels[status]} saved.`);}catch(error){setMessage(error instanceof Error?`${error.message} Your local change was not accepted.`:"Attendance did not save. Reload and try again.");await load(selectedId);}finally{setSavingStudents((current)=>{const next=new Set(current);next.delete(row.studentId);return next;});}};
  const addWalkIn=async()=>{const student=students.find((item)=>item.id===walkIn);if(!student)return;await updateAttendance({studentId:student.id,displayName:student.displayName,registrationStatus:"registered",registrationSource:"walk_in",attendanceStatus:"not_recorded",attendanceSource:null,version:0,updatedAt:new Date().toISOString()},"present");setWalkIn("");await load(selectedId);};
  const setCheckin=async(action:"open"|"close")=>{setBusy(true);try{const result=await api.request<{open:boolean;token?:string;closesAt?:string;deepLink?:string}>("/api/oaca/events/check-in",{method:"POST",body:{eventId:selectedId,action,minutes:120}});setCheckinToken(result.token||"");setCheckinUrl(result.deepLink?`${window.location.origin}${result.deepLink}`:"");setCheckinCloses(result.closesAt||"");setMessage(action==="open"?"Check-in is open. The static event QR works until staff close this window.":"Check-in is closed; the event QR is no longer valid.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"Check-in could not be changed.");}finally{setBusy(false);}};
  const scan=async(token=scanToken)=>{if(!token)return;setBusy(true);try{await api.request("/api/oaca/events/check-in/scan",{method:"POST",body:{eventId:selectedId,token}});setScanToken("");setMessage("Student checked in. Repeated scans will not create a duplicate attendance record.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The student code could not be accepted.");}finally{setBusy(false);}};
  const onScanImage=async(file?:File)=>{if(!file)return;try{const value=await detectQrFromImage(file);if(!value)throw new Error("No QR code was found in that image.");setScanToken(value);await scan(value);}catch(error){setMessage(error instanceof Error?error.message:"The image could not be scanned.");}};
  const sendNotice=async()=>{setBusy(true);try{await api.request("/api/oaca/event-notifications",{method:"POST",body:{eventId:selectedId,type:noticeType,title:noticeTitle,body:noticeBody,channels:notificationChannels({email,push,sms}),audience:allActive?"invited":"registered",generation:crypto.randomUUID()}});setMessage("The Compass notice is available now. Eligible external channels were queued around each recipient’s quiet hours.");setNoticeBody("");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The notification could not be created.");}finally{setBusy(false);}};
  const sendThread=async()=>{const thread=workspace.threads.find((item)=>item.id===activeThread?.id);if(!thread||!threadBody.trim())return;setBusy(true);try{await api.request("/api/oaca/event-messages",{method:"POST",body:{eventId:selectedId,studentId:thread.studentId,body:threadBody,channel:threadSms?"sms":"in_app"}});setThreadBody("");setMessage(threadSms?"Reply retained in Compass and queued for consented SMS delivery.":"Reply saved in the event conversation.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The reply could not be sent.");}finally{setBusy(false);}};
  const saveDetails=async()=>{setBusy(true);try{await api.request("/api/oaca/events/update",{method:"POST",body:{eventId:selectedId,...edit,startsAt:toIso(edit.startsAt),endsAt:edit.endsAt?toIso(edit.endsAt):null,capacity:edit.capacity||null}});setMessage("Event changes saved. Applicable notifications were rescheduled.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The event could not be updated.");}finally{setBusy(false);}};
  const cancelEvent=async()=>{setBusy(true);try{await api.request("/api/oaca/events/cancel",{method:"POST",body:{eventId:selectedId,channels:notificationChannels({email,push,sms})}});setMessage("Event cancelled. Check-in closed and cancellation notices were created.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The event could not be cancelled.");}finally{setBusy(false);}};
  const publishExisting=async()=>{setBusy(true);try{const saved=await api.request<{status:string}>("/api/oaca/events/publish",{method:"POST",body:{eventId:selectedId}});setMessage(saved.status==="published"?"Event published. Recipients were resolved and invitation settings applied.":"The event remains a draft. Review the publication requirements and try again.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The event could not be published.");}finally{setBusy(false);}};
  const assignCoordinator=async()=>{if(!hostUser)return;setBusy(true);try{await api.request("/api/oaca/events/hosts",{method:"POST",body:{eventId:selectedId,userId:hostUser,role:"owner"}});setHostUser("");setMessage("Coordinator added as an owner and check-in staff member.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The coordinator could not be added.");}finally{setBusy(false);}};
  const removeCoordinator=async(userId:string)=>{setBusy(true);try{await api.request("/api/oaca/events/hosts",{method:"DELETE",body:{eventId:selectedId,userId}});setMessage("Coordinator access and future alerts were removed.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The coordinator could not be removed.");}finally{setBusy(false);}};
  const saveCoordinatorRules=async()=>{setBusy(true);try{await api.request("/api/oaca/event-coordinator-alert-rules",{method:"POST",body:{eventId:selectedId,rules:workspace.coordinatorAlertRules}});setMessage("Coordinator alert routing saved for this event.");await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"Coordinator alert settings could not be saved.");}finally{setBusy(false);}};
  const previewRecipientRefresh=async()=>{if(!selected)return;try{setRefreshPreview(await api.request<Preview>("/api/oaca/events/recipients/refresh",{method:"POST",body:{eventId:selected.id,audience:selected.audience,commit:false}}));}catch(error){setMessage(error instanceof Error?error.message:"Recipient changes could not be previewed.");}};
  const commitRecipientRefresh=async()=>{if(!selected)return;setBusy(true);try{const result=await api.request<Preview>("/api/oaca/events/recipients/refresh",{method:"POST",body:{eventId:selected.id,audience:selected.audience,commit:true}});setRefreshPreview(null);setMessage(`Recipient version ${result.version} saved. ${result.additions||0} new invitations were created.`);await load(selected.id);}catch(error){setMessage(error instanceof Error?error.message:"Recipients could not be refreshed.");}finally{setBusy(false);}};
  const resolveCorrection=async(correctionId:string,decision:"approve"|"decline")=>{setBusy(true);try{await api.request("/api/oaca/events/corrections/resolve",{method:"POST",body:{correctionId,decision}});setMessage(`Correction ${decision==="approve"?"approved and applied":"declined"}.`);await load(selectedId);}catch(error){setMessage(error instanceof Error?error.message:"The correction could not be resolved.");}finally{setBusy(false);}};
  const uploadImport=async()=>{if(!eventsFile||!logsFile)return;setBusy(true);setMessage("Uploading both originals to private quarantine…");try{const upload=async(file:File,purpose:string)=>{if(file.size>25*1024*1024)throw new Error("Each import file must be 25 MB or smaller.");const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,"-");const path=`${context.userId}/oaca/event-imports/${crypto.randomUUID()}-${safeName}`;const result=await supabase.storage.from("platform-files").upload(path,file,{contentType:file.type||"text/csv",upsert:false});if(result.error)throw new Error("A private import upload failed.");return api.request<{id:string}>("/api/platform/files",{method:"POST",body:{experienceKey:"oaca",storagePath:path,originalName:file.name,mimeType:file.type||"text/csv",sizeBytes:file.size,purpose}});};const [eventsRecord,logsRecord]=await Promise.all([upload(eventsFile,"penji_event_master"),upload(logsFile,"penji_event_attendance")]);await api.request("/api/oaca/event-imports",{method:"POST",body:{eventsFileId:eventsRecord.id,attendanceFileId:logsRecord.id}});setEventsFile(undefined);setLogsFile(undefined);setMessage(isSynthetic?"Synthetic import complete. The 22 sanitized Penji occurrences are available in Past.":"Paired import created. The status below shows the next security or review step.");setBucket("past");await load("");}catch(error){setMessage(error instanceof Error?error.message:"The paired import could not be created.");}finally{setBusy(false);}};
  const reviewImport=async(packageId:string,decision:"approve"|"reject")=>{setBusy(true);try{await api.request("/api/oaca/event-imports/review",{method:"POST",body:{packageId,decision}});setMessage(decision==="approve"?"Import approved. Secure normalization is queued.":"Import rejected; neither file will be processed.");await load("");}catch(error){setMessage(error instanceof Error?error.message:"The import decision could not be saved.");}finally{setBusy(false);}};
  const resetSynthetic=async()=>{await api.request("/api/oaca/synthetic/reset",{method:"POST",body:{}});setSelectedId("");setBucket("past");setMessage("Synthetic event data reset. The sanitized Penji history is restored.");await load("");};

  if(!selected)return <section className="experience-panel event-workspace">
    <button className="workspace-back text-button" onClick={onBack}>← Staff home</button>
    <div className="section-heading"><div><p className="kicker">Compass events</p><h1>Events</h1><p>{canCreateEvents?"Create, publish, communicate, and run attendance from one workspace.":"Browse current and past Compass event summaries. Private rosters and activity stay with event coordinators."}</p></div><div className="workspace-actions">{canCreateEvents?<button className="primary-button" onClick={()=>setShowCreator((value)=>!value)}>{showCreator?"Close event builder":"Create event"}</button>:null}{isSynthetic&&canCreateEvents?<button className="secondary-button" onClick={()=>void resetSynthetic()}>Reset synthetic data</button>:null}</div></div>
    <p className="form-message" aria-live="polite">{message}</p>
    <section className="staff-event-inbox" aria-labelledby="staff-event-inbox-title">
      <div className="section-heading"><div><p className="kicker">Staff and host notifications</p><h2 id="staff-event-inbox-title">Event activity</h2></div><span className="status-chip status-chip--pending">{workspace.notifications.filter((notice)=>staffCategory(notice)&&!notice.readAt).length} unread</span></div>
      <div className="staff-event-inbox__filters"><label><span>Event</span><select value={noticeEvent} onChange={(event)=>setNoticeEvent(event.target.value)}><option value="">All events</option>{workspace.events.map((event)=><option key={event.id} value={event.id}>{event.title}</option>)}</select></label><label><span>Activity</span><select value={noticeTypeFilter} onChange={(event)=>setNoticeTypeFilter(event.target.value)}><option value="">All activity</option>{staffNoticeTypes.map((type)=><option key={type} value={type}>{notificationLabel(type)}</option>)}</select></label></div>
      <div className="staff-event-inbox__list">{staffNotices.map((notice)=><article key={notice.id} className={notice.readAt?"read":"unread"}><div><span>{notificationLabel(notice.category)}</span><strong>{notice.title}</strong><p>{notice.body}</p><small>{new Date(notice.createdAt).toLocaleString()}</small></div><div className="workspace-actions">{!notice.readAt?<button className="text-button" onClick={()=>void actOnNotice(notice.id,"read")}>Mark read</button>:null}{notice.eventId?<button className="secondary-button" onClick={()=>void openEvent(notice.eventId!,notice.category.includes("message"))}>Open</button>:null}<button className="text-button" onClick={()=>void actOnNotice(notice.id,"dismiss")}>Dismiss</button></div></article>)}{!staffNotices.length?<p>No coordinator notifications match these filters.</p>:null}</div>
    </section>
    {showCreator&&canCreateEvents?<section className="event-builder" aria-labelledby="event-builder-title">
      <div className="event-builder__heading"><div><p className="kicker">New event</p><h2 id="event-builder-title">Build and publish</h2></div><span>Step {wizardStep+1} of {wizardSteps.length}</span></div>
      <nav className="event-wizard-steps" aria-label="Event creation steps">{wizardSteps.map((step,index)=><button key={step} className={index===wizardStep?"active":index<wizardStep?"complete":""} onClick={()=>setWizardStep(index)} aria-current={index===wizardStep?"step":undefined}><i aria-hidden="true">{index<wizardStep?"✓":index+1}</i>{step}</button>)}</nav>
      {wizardStep===0?<div className="event-form-grid"><label><span>Event title</span><input value={draft.title} onChange={(event)=>setDraft({...draft,title:event.target.value})}/></label><label><span>Category</span><select value={draft.category} onChange={(event)=>setDraft({...draft,category:event.target.value})}><option>Academic support</option><option>Career</option><option>Community</option><option>Well-being</option></select></label><label><span>Format</span><select value={draft.modality} onChange={(event)=>setDraft({...draft,modality:event.target.value})}><option value="in_person">In person</option><option value="teams">Teams</option><option value="hybrid">Hybrid</option></select></label><label className="event-builder__wide"><span>Description</span><textarea rows={4} value={draft.description} onChange={(event)=>setDraft({...draft,description:event.target.value})}/></label><label className="event-builder__wide"><span>Accessibility details</span><input value={draft.accessibilityDetails} onChange={(event)=>setDraft({...draft,accessibilityDetails:event.target.value})} placeholder="How students can request access support or accommodations"/></label><label><span>Starts</span><input type="datetime-local" value={draft.startsAt} onChange={(event)=>setDraft({...draft,startsAt:event.target.value})}/></label><label><span>Ends</span><input type="datetime-local" value={draft.endsAt} onChange={(event)=>setDraft({...draft,endsAt:event.target.value})}/></label><label><span>Location or meeting details</span><input value={draft.location} onChange={(event)=>setDraft({...draft,location:event.target.value})}/></label><label><span>Capacity</span><input type="number" min="1" value={draft.capacity} onChange={(event)=>setDraft({...draft,capacity:event.target.value})} placeholder="Leave blank for unlimited"/></label><label className="check-row event-builder__wide"><input type="checkbox" checked={draft.publicCatalog} onChange={(event)=>setDraft({...draft,publicCatalog:event.target.checked})}/><span>Show this event’s non-sensitive summary in the student All Public history after it ends.</span></label></div>:null}
      {wizardStep===1?<div className="audience-builder"><label className="audience-builder__all"><input type="checkbox" checked={Boolean(draft.audience.includeAllMembers)} onChange={(event)=>{setDraft((current)=>({...current,audience:{...current.audience,includeAllMembers:event.target.checked}}));setPreview(null);}}/><span>All campus community<small>Every active Compass account in the RUCOM pilot.</small></span></label><div className="audience-builder__groups">{[["Classes and cohorts","cohortLabels",workspace.audienceOptions.cohorts],["Academic phase","phases",workspace.audienceOptions.phases],["Academic year","years",workspace.audienceOptions.years],["Campus","campuses",workspace.audienceOptions.campuses]].map(([label,key,values])=><fieldset key={String(key)}><legend>{String(label)}</legend>{(values as string[]).map((value)=><label key={value}><input type="checkbox" checked={Boolean((draft.audience[key as keyof OacaAudience] as string[]|undefined)?.includes(value))} onChange={(event)=>setAudienceValues(key as keyof OacaAudience,value,event.target.checked)}/><span>{value}</span></label>)}</fieldset>)}<fieldset><legend>Faculty and staff groups</legend>{workspace.audienceOptions.memberRoles.map((role)=><label key={role.key}><input type="checkbox" checked={draft.audience.memberRoles?.includes(role.key)||false} onChange={(event)=>setAudienceValues("memberRoles",role.key,event.target.checked)}/><span>{role.label}</span></label>)}</fieldset><fieldset><legend>Students assigned to an advisor</legend>{workspace.audienceOptions.providers.map((provider)=><label key={provider.id}><input type="checkbox" checked={draft.audience.assignedProviderIds?.includes(provider.id)||false} onChange={(event)=>setAudienceValues("assignedProviderIds",provider.id,event.target.checked)}/><span>{provider.displayName}</span></label>)}</fieldset></div><details className="audience-builder__details"><summary>Student interest groups and Student Council</summary><label><input type="checkbox" checked={Boolean(draft.audience.studentCouncil)} onChange={(event)=>{setDraft((current)=>({...current,audience:{...current.audience,studentCouncil:event.target.checked}}));setPreview(null);}}/><span>Student Council</span></label><div className="audience-builder__scroll">{workspace.audienceOptions.organizations.map((organization)=><label key={organization.id}><input type="checkbox" checked={draft.audience.organizationIds?.includes(organization.id)||false} onChange={(event)=>setAudienceValues("organizationIds",organization.id,event.target.checked)}/><span>{organization.name}<small>{organization.college}</small></span></label>)}</div></details><details className="audience-builder__details"><summary>Named people and exclusions</summary><div className="audience-builder__people"><fieldset><legend>Include named people</legend>{workspace.audienceOptions.people.map((person)=><label key={`include-${person.userId}`}><input type="checkbox" checked={draft.audience.userIds?.includes(person.userId)||false} onChange={(event)=>setAudienceValues("userIds",person.userId,event.target.checked)}/><span>{person.displayName}<small>{person.role}</small></span></label>)}</fieldset><fieldset><legend>Exclude named people</legend>{workspace.audienceOptions.people.map((person)=><label key={`exclude-${person.userId}`}><input type="checkbox" checked={draft.audience.excludeUserIds?.includes(person.userId)||false} onChange={(event)=>setAudienceValues("excludeUserIds",person.userId,event.target.checked)}/><span>{person.displayName}</span></label>)}</fieldset></div></details><div className="audience-preview"><div><span>Audience rule</span><strong>{describeOacaAudience(draft.audience)}</strong></div><button className="secondary-button" onClick={()=>void previewAudience()}>Preview recipients</button>{preview?<div><strong>{preview.count} unique recipients</strong><span>{preview.excludedCount} excluded</span><small>{preview.sample.map((person)=>person.displayName).join(", ")}{preview.count>preview.sample.length?"…":""}</small></div>:null}</div></div>:null}
      {wizardStep===2?<div className="coordinator-picker"><p>Coordinators can edit, publish, cancel, message, open the roster, and check attendees in. Each selection is saved by name.</p>{staffGroups.map(([label,people])=><fieldset key={label}><legend>{label}</legend>{people.map((person)=><label key={person.userId}><input type="checkbox" checked={draft.coordinatorUserIds.includes(person.userId)} disabled={person.userId===context.userId} onChange={(event)=>setDraft((current)=>({...current,coordinatorUserIds:toggleValue(current.coordinatorUserIds,person.userId,event.target.checked)}))}/><span><strong>{person.displayName}</strong>{person.userId===context.userId?<small>Event creator · required</small>:null}</span></label>)}</fieldset>)}</div>:null}
      {wizardStep===3?<div className="notification-builder"><section><h3>Attendee communications</h3><p>Every enabled notice is recorded in Compass. Choose additional delivery channels.</p><div className="notification-matrix">{draft.attendeeRules.map((rule,index)=><article key={`${rule.type}-${rule.offsetMinutes}`}><label className="notification-matrix__title"><input type="checkbox" checked={rule.enabled} onChange={(event)=>updateAttendeeRule(index,{enabled:event.target.checked})}/><span>{rule.label}</span></label><ChannelChecks email={rule.email} push={rule.push} sms={rule.sms} onChange={(field,checked)=>updateAttendeeRule(index,{[field]:checked})}/></article>)}</div></section><section><h3>Coordinator alerts</h3><p>Immediate alerts arrive separately. Hourly alerts are combined into one digest.</p><div className="notification-matrix">{draft.coordinatorRules.map((rule,index)=><article key={rule.activityType}><label><span>{rule.label}</span><select value={rule.deliveryMode} onChange={(event)=>updateCoordinatorRule(index,{deliveryMode:event.target.value as CoordinatorRuleDraft["deliveryMode"]})}><option value="immediate">Immediate</option><option value="hourly">Hourly summary</option><option value="off">Off</option></select></label><ChannelChecks email={rule.email} push={rule.push} sms={rule.sms} onChange={(field,checked)=>updateCoordinatorRule(index,{[field]:checked})}/></article>)}</div></section></div>:null}
      {wizardStep===4?<div className="event-review"><div><span>Event</span><strong>{draft.title||"Title needed"}</strong><small>{draft.startsAt?new Date(draft.startsAt).toLocaleString():"Start time needed"}{draft.location?` · ${draft.location}`:""}</small></div><div><span>Audience</span><strong>{describeOacaAudience(draft.audience)}</strong><small>{preview?`${preview.count} previewed recipients`:"Preview recipients before publishing"}</small></div><div><span>Coordinators</span><strong>{draft.coordinatorUserIds.length} selected</strong><small>{draft.coordinatorUserIds.map((id)=>workspace.staffOptions.find((person)=>person.userId===id)?.displayName||id).join(", ")}</small></div><div><span>Notifications</span><strong>{draft.attendeeRules.filter((rule)=>rule.enabled).length} attendee rules</strong><small>Coordinator routing reviewed for {draft.coordinatorRules.length} activity types.</small></div>{!publishReady?<p className="form-message">Complete every section and review notification settings before publishing.</p>:null}</div>:null}
      <div className="event-builder__actions">{wizardStep>0?<button className="text-button" onClick={()=>setWizardStep((step)=>step-1)}>Back</button>:<span/>}{wizardStep<wizardSteps.length-1?<button className="primary-button" onClick={async()=>{if(wizardStep===1)await previewAudience();if(wizardStep===3)setNotificationsReviewed(true);setWizardStep((step)=>step+1);}}>Continue</button>:<div className="workspace-actions"><button className="secondary-button" disabled={busy} onClick={()=>void createEvent("draft")}>Save draft</button><button className="primary-button" disabled={busy||!publishReady} onClick={()=>void createEvent("publish")}>{busy?"Publishing…":"Publish event"}</button></div>}</div>
    </section>:null}
    <div className="event-list-toolbar"><label>From<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>Through<input type="date" min={dateFrom} value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><button className="text-button" onClick={()=>{setDateFrom("");setDateTo("");}}>Clear date range</button><nav className="event-bucket-tabs" aria-label="Event timeframe">{(["today","upcoming","past"] as const).map((value)=><button key={value} className={bucket===value?"active":""} onClick={()=>setBucket(value)}>{value[0].toUpperCase()+value.slice(1)} <span>{workspace.events.filter((event)=>eventBucket(event.startsAt,event.endsAt)===value).length}</span></button>)}</nav><label className="event-search"><span className="sr-only">Search events</span><input type="search" placeholder="Search title or location" value={query} onChange={(event)=>setQuery(event.target.value)}/></label></div>
    <div className="event-list">{filteredEvents.map((event)=><button key={event.id} onClick={()=>void openEvent(event.id)}><span className="event-date"><strong>{new Date(event.startsAt).toLocaleDateString(undefined,{month:"short",day:"numeric"})}</strong><span>{new Date(event.startsAt).toLocaleTimeString(undefined,{hour:"numeric",minute:"2-digit"})}</span></span><span><strong>{event.title}</strong><small>{event.location||event.modality.replaceAll("_"," ")} · {event.registrationCount} rostered</small><small>{event.sourceSystem==="penji"?"Penji history · ":""}{event.status.replaceAll("_"," ")}{!event.canManage?" · Summary only":""}</small></span><span className="event-count">{event.presentCount} present</span></button>)}{!filteredEvents.length?<div className="empty-state"><h2>No {bucket} events</h2><p>Try another timeframe or create a new event.</p></div>:null}</div>
    {canManageImports?<details className="event-admin-card"><summary>Import Penji events and attendance</summary><p>Upload the event master and attendance log together. Production files remain quarantined until scanning and independent approval are complete.</p><div className="paired-import"><label className="file-drop"><span>{eventsFile?.name||"Choose event export CSV"}</span><input type="file" accept=".csv,text/csv" onChange={(event)=>setEventsFile(event.target.files?.[0])}/></label><label className="file-drop"><span>{logsFile?.name||"Choose attendance log CSV"}</span><input type="file" accept=".csv,text/csv" onChange={(event)=>setLogsFile(event.target.files?.[0])}/></label></div><button className="primary-button" disabled={busy||!eventsFile||!logsFile} onClick={()=>void uploadImport()}>{busy?"Securing files…":"Create paired import"}</button>{importPackages.length?<div className="import-package-list">{importPackages.map((item)=><article key={item.id}><div><span className={`status-chip status-chip--${["completed","completed_with_issues"].includes(item.status)?"confirmed":"pending"}`}>{item.status.replaceAll("_"," ")}</span><strong>{new Date(item.created_at).toLocaleString()}</strong><small>{item.source_event_rows} event rows · {item.source_attendance_rows} attendance rows · {item.occurrence_count} occurrences · {item.merged_duplicates} safely merged</small><ImportProgress item={item}/></div>{item.status==="ready_for_review"?<div className="workspace-actions"><button className="secondary-button" disabled={busy||item.requested_by===context.userId} onClick={()=>void reviewImport(item.id,"approve")}>Approve import</button><button className="text-button" disabled={busy} onClick={()=>void reviewImport(item.id,"reject")}>Reject</button></div>:null}</article>)}</div>:null}</details>:null}
  </section>;

  if(!selected.canManage)return <section className="experience-panel event-workspace"><button className="workspace-back text-button" onClick={()=>setSelectedId("")}>← All events</button><p className="kicker">Event summary</p><h1>{selected.title}</h1><p>{selected.description}</p><div className="event-stat-strip"><span><strong>{new Date(selected.startsAt).toLocaleDateString()}</strong>Date</span><span><strong>{selected.location||selected.modality}</strong>Location</span><span><strong>{selected.registrationCount}</strong>Rostered</span></div><p className="policy-intro">Identifiable attendance, conversations, and correction requests are limited to this event’s coordinators.</p></section>;

  return <section className="experience-panel event-workspace">
    <button className="workspace-back text-button" onClick={()=>{setSelectedId("");setRefreshPreview(null);void load("");}}>← All events</button>
    <div className="event-detail-header"><div><p className="kicker">{selected.status.replaceAll("_"," ")}</p><h1>{selected.title}</h1><p>{new Date(selected.startsAt).toLocaleString()} · {selected.location||selected.modality.replaceAll("_"," ")}</p></div><div className="event-stat-strip"><span><strong>{selected.registrationCount}</strong>Rostered</span><span><strong>{selected.presentCount}</strong>Present</span><span><strong>{selected.absentCount}</strong>Absent</span><span><strong>{selected.notRecordedCount}</strong>Not recorded</span></div></div>
    <p className="form-message" aria-live="polite">{message}</p>
    <nav className="event-detail-tabs" aria-label="Event workspace">{(["attendance","checkin","notify","messages","details"] as DetailTab[]).map((value)=><button key={value} className={tab===value?"active":""} onClick={()=>setTab(value)}>{value==="notify"?"Notifications":value==="messages"?"Conversations":value[0].toUpperCase()+value.slice(1)}</button>)}</nav>
    {tab==="attendance"?<div><div className="walk-in-bar"><label><span>Walk-in search</span><select value={walkIn} onChange={(event)=>setWalkIn(event.target.value)}><option value="">Find an active student</option>{students.filter((student)=>!workspace.roster.some((row)=>row.studentId===student.id)).map((student)=><option key={student.id} value={student.id}>{student.displayName}</option>)}</select></label><button className="primary-button" disabled={!walkIn} onClick={()=>void addWalkIn()}>Register and mark present</button></div><div className="attendance-list">{workspace.roster.map((row)=><article key={row.studentId}><div><strong>{row.displayName}</strong><small>{row.registrationSource.replaceAll("_"," ")}{savingStudents.has(row.studentId)?" · Saving…":` · v${row.version}`}</small></div><AttendanceControl row={row} disabled={savingStudents.has(row.studentId)} onChange={(record,status)=>void updateAttendance(record,status)}/></article>)}{!workspace.roster.length?<div className="empty-state"><h2>No attendees yet</h2><p>Use walk-in search to register and mark a student present.</p></div>:null}</div>{workspace.corrections.filter((item)=>item.status==="open").length?<div className="correction-stack"><h2>Correction requests</h2>{workspace.corrections.filter((item)=>item.status==="open").map((item)=><article key={item.id}><div><strong>{item.displayName}</strong><p>Requests {attendanceLabels[item.requestedStatus]}. {item.explanation}</p></div><div className="workspace-actions"><button className="secondary-button" disabled={busy} onClick={()=>void resolveCorrection(item.id,"approve")}>Approve</button><button className="text-button" disabled={busy} onClick={()=>void resolveCorrection(item.id,"decline")}>Decline</button></div></article>)}</div>:null}</div>:null}
    {tab==="checkin"?<div className="checkin-grid"><article className="event-admin-card"><h2>Static event QR</h2><p>Students may self-check in only while coordinators keep this window open.</p>{checkinToken?<><QrImage value={checkinUrl} label={`Check-in QR for ${selected.title}`}/><small>Open until {new Date(checkinCloses).toLocaleTimeString()}</small></>:<div className="empty-state"><p>{selected.checkinOpen?"A check-in session is already open.":"Check-in is closed."}</p></div>}<div className="workspace-actions"><button className="primary-button" disabled={busy} onClick={()=>void setCheckin("open")}>Open check-in</button><button className="secondary-button" disabled={busy} onClick={()=>void setCheckin("close")}>Close</button></div></article><article className="event-admin-card"><h2>Scan a student’s Compass QR</h2><label className="file-drop"><span>Use camera or choose QR image</span><input type="file" accept="image/*" capture="environment" onChange={(event)=>void onScanImage(event.target.files?.[0])}/></label><label><span>Accessible manual fallback</span><input value={scanToken} onChange={(event)=>setScanToken(event.target.value)} placeholder="Paste the opaque student code"/></label><button className="primary-button" disabled={busy||!scanToken} onClick={()=>void scan()}>Check student in</button></article></div>:null}
    {tab==="notify"?<div className="notification-workspace"><article className="event-admin-card"><h2>Attendee notifications</h2>{workspace.notificationRules.map((rule)=><div className="reminder-row" key={`${rule.type}-${rule.offsetMinutes}`}><div><strong>{rule.type==="reminder"?`${rule.offsetMinutes===1440?"24-hour":"1-hour"} reminder`:rule.type.replaceAll("_"," ")}</strong><small>{rule.enabled?rule.channels.join(", "):"Disabled"}</small></div></div>)}<button className="secondary-button" onClick={()=>{setNoticeType("announcement");setNoticeTitle(selected.title);}}>Prepare one-time notice</button></article><article className="event-admin-card"><h2>Coordinator alert routing</h2>{workspace.coordinatorAlertRules.map((rule,index)=><div className="reminder-row" key={rule.activityType}><div><strong>{rule.activityType.replaceAll("_"," ")}</strong><small>{rule.channels.join(", ")}</small></div><select aria-label={`${rule.activityType} delivery mode`} value={rule.deliveryMode} onChange={(event)=>setWorkspace((current)=>({...current,coordinatorAlertRules:current.coordinatorAlertRules.map((item,itemIndex)=>itemIndex===index?{...item,deliveryMode:event.target.value as CoordinatorRule["deliveryMode"]}:item)}))}><option value="immediate">Immediate</option><option value="hourly">Hourly summary</option><option value="off">Off</option></select></div>)}<button className="secondary-button" disabled={busy} onClick={()=>void saveCoordinatorRules()}>Save coordinator routing</button></article><article className="event-admin-card"><h2>Send one-time event notice</h2><label><span>Type</span><select value={noticeType} onChange={(event)=>setNoticeType(event.target.value)}>{["publication","event_change","cancellation","checkin_open","follow_up","announcement"].map((value)=><option key={value} value={value}>{value.replaceAll("_"," ")}</option>)}</select></label><label><span>Title</span><input value={noticeTitle} onChange={(event)=>setNoticeTitle(event.target.value)}/></label><label><span>Message</span><textarea value={noticeBody} onChange={(event)=>setNoticeBody(event.target.value)} placeholder="Event details and a secure Compass link only."/></label><ChannelChecks email={email} push={push} sms={sms} onChange={(field,checked)=>{if(field==="email")setEmail(checked);if(field==="push")setPush(checked);if(field==="sms")setSms(checked);}}/><label className="check-row"><input type="checkbox" checked={allActive} onChange={(event)=>setAllActive(event.target.checked)}/><span>Send to the current invited audience instead of only registered attendees</span></label><button className="primary-button" disabled={busy||!noticeTitle.trim()} onClick={()=>void sendNotice()}>Create and queue notice</button></article><article className="event-admin-card"><h2>Recipient version {workspace.recipientVersion||"—"}</h2><p>{workspace.recipientCount} current invitation recipients. Membership changes do not send invitations automatically.</p><button className="secondary-button" onClick={()=>void previewRecipientRefresh()}>Refresh recipients</button>{refreshPreview?<div className="recipient-refresh"><strong>{refreshPreview.count} recipients after refresh</strong><span>{refreshPreview.additions||0} additions · {refreshPreview.removals||0} removals</span><small>Removed recipients keep an existing RSVP until staff change it.</small><button className="primary-button" disabled={busy} onClick={()=>void commitRecipientRefresh()}>Confirm recipient changes</button></div>:null}</article><article className="event-delivery-card"><h2>Delivery results</h2><div className="event-stat-strip">{["queued","suppressed","sent","delivered","failed","opened","clicked","replied"].map((status)=><span key={status}><strong>{workspace.deliveries[status]||0}</strong>{status}</span>)}</div></article></div>:null}
    {tab==="messages"?<div className="event-message-layout"><aside><h2>Event conversations</h2><p>New replies also appear in the staff event activity inbox.</p>{workspace.threads.map((thread)=><button className={activeThread?.id===thread.id?"active":""} key={thread.id} onClick={()=>setThreadId(thread.id)}><strong>{thread.studentName}</strong><small>{thread.messages.at(-1)?.body||"No messages"}</small></button>)}</aside><section>{activeThread?<><div className="event-message-log" aria-live="polite">{activeThread.messages.map((item)=><article key={item.id} className={item.senderId===context.userId?"mine":"theirs"}><p>{item.body}</p><small>{item.channel.toUpperCase()} · {new Date(item.createdAt).toLocaleString()}</small></article>)}</div><label><span>Reply to {activeThread.studentName}</span><textarea value={threadBody} onChange={(event)=>setThreadBody(event.target.value)}/></label><label className="check-row"><input type="checkbox" checked={threadSms} onChange={(event)=>setThreadSms(event.target.checked)}/><span>Also deliver by SMS if verified and consented</span></label><button className="primary-button" disabled={busy||!threadBody.trim()} onClick={()=>void sendThread()}>Send reply</button></>:<div className="empty-state"><h2>No conversation selected</h2></div>}</section></div>:null}
    {tab==="details"?<div className="event-details-grid"><article className="event-admin-card"><h2>Edit event</h2>{selected.publicationError?<p className="form-message">Last publication attempt: {selected.publicationError}</p>:null}<label><span>Title</span><input value={edit.title} onChange={(event)=>setEdit({...edit,title:event.target.value})}/></label><label><span>Category</span><select value={edit.category} onChange={(event)=>setEdit({...edit,category:event.target.value})}><option>Academic support</option><option>Career</option><option>Community</option><option>Well-being</option></select></label><label><span>Description</span><textarea value={edit.description} onChange={(event)=>setEdit({...edit,description:event.target.value})}/></label><label><span>Accessibility details</span><input value={edit.accessibilityDetails} onChange={(event)=>setEdit({...edit,accessibilityDetails:event.target.value})}/></label><div className="form-row"><label><span>Starts</span><input type="datetime-local" value={edit.startsAt} onChange={(event)=>setEdit({...edit,startsAt:event.target.value})}/></label><label><span>Ends</span><input type="datetime-local" value={edit.endsAt} onChange={(event)=>setEdit({...edit,endsAt:event.target.value})}/></label></div><div className="form-row"><label><span>Location</span><input value={edit.location} onChange={(event)=>setEdit({...edit,location:event.target.value})}/></label><label><span>Capacity</span><input type="number" min="1" value={edit.capacity} onChange={(event)=>setEdit({...edit,capacity:event.target.value})} placeholder="Unlimited"/></label></div><label className="check-row"><input type="checkbox" checked={edit.publicCatalog} onChange={(event)=>setEdit({...edit,publicCatalog:event.target.checked})}/><span>Show the non-sensitive summary in All Public history after the event ends.</span></label><button className="secondary-button" disabled={busy} onClick={()=>void saveDetails()}>Save changes</button>{selected.status==="draft"?<button className="primary-button" disabled={busy} onClick={()=>void publishExisting()}>Publish event</button>:null}<button className="text-button event-cancel-button" disabled={busy||selected.status==="cancelled"} onClick={()=>void cancelEvent()}>{selected.status==="cancelled"?"Event cancelled":"Cancel event and notify attendees"}</button></article><article className="event-admin-card"><h2>Event coordinators</h2><p>Every coordinator is an owner and check-in staff member.</p>{workspace.hosts.filter((host)=>host.role==="owner").map((host)=><div className="host-row" key={host.userId}><div><strong>{host.displayName}</strong><small>Owner · check-in · notifications</small></div><button className="text-button" disabled={busy||workspace.hosts.filter((item)=>item.role==="owner").length===1} onClick={()=>void removeCoordinator(host.userId)}>Remove</button></div>)}<label><span>Add named coordinator</span><select value={hostUser} onChange={(event)=>setHostUser(event.target.value)}><option value="">Choose Compass staff</option>{staffGroups.map(([label,people])=><optgroup key={label} label={label}>{people.filter((person)=>!workspace.hosts.some((host)=>host.userId===person.userId)).map((person)=><option key={person.userId} value={person.userId}>{person.displayName}</option>)}</optgroup>)}</select></label><button className="secondary-button" disabled={busy||!hostUser} onClick={()=>void assignCoordinator()}>Add coordinator</button></article></div>:null}
  </section>;
}
